quests[36662] = { id = 36662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrappin'", description = "Ever since we built da menagerie, a lot o' \"visitors\" been showin' up.  I know da look, and they be lookin' for a fight.  <Brudda/Sista>, you show 'em you da real master 'round here.", progress = "Did you show 'em the mojo?", completion = "You showed 'em, boss!", objectives = "Defeat the pets in the battle area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
