quests[36667] = { id = 36667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Shattrath Harbor", description = "Shattrath City is in the hands of Sargerei forces under the leadership of the once Exarch, Socrethar.\n\nThe Shadow Council forces in the eastern portion of the city are gaining in power through the aid of demons from the Nether, and need to be culled before they become a threat to all of our operations.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Sargerei forces at Shattrath City in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36669] = { id = 36669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Stonefury Cliffs", description = "Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines.\n\nShadow Hunter Rokhan has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36670] = { id = 36670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Blood: Skull Chewer!", description = "Welcome to Nagrand's one and only Ring of Blood, where hopefuls become gladiators and gladiators become discarded piles of meat on the arena floor!\n\nTalk to me to start a fight, hop down into the ring, and fight for your life. It's positively brutal - and the crowd loves it!\n\nYou'll face off against an ogron that has a hankering for freshly severed heads. You'll be fine... and I'll be rich!", completion = "Nicely done, pal. Now how's about we kick things up a notch?", objectives = "Defeat Skull Chewer in the Ring of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36671] = { id = 36671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Blood: Fracktus!", description = "Have you ever fought a living, breathing mountain that wants to murder your face? Well, today's your lucky day!\n\nFracktus is a... well... living, breathing mountain that wants to murder your face, actually. Got that one right the first time!\n\nJust hop in the ring so we can get started, will ya?", completion = "Incredible! You've got real moxy, kid.", objectives = "Defeat Fracktus in the Ring of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36672] = { id = 36672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Blood: Venoxis!", description = "Alright, alright, how about this. A living, breathing... wait for it.... tree... that wants to murder your face. Genius, right?\n\nLook, they don't pay me to come up with witty dialogue about these things, give me a break. They're ogres - they pay for blood. Hence the name.", completion = "You're the best I've ever seen in all my years as a promoter. I really mean that.", objectives = "Defeat Venoxis in the Ring of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36673] = { id = 36673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Blood: Dreshax!", description = "You're going to love this one, champ.\n\nThat's right, it's the largest bone worm this side of Draenor. Dreshax lovingly disposes of all of the suckers... I mean... fallen gladiators for us.\n\nThink you've got what it takes? Hop on in and wait. Dreshax's lair is just below the arena - he'll come to you.", completion = "What a battle. What a fight! Incredible!", objectives = "Defeat Dreshax in the Ring of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36674] = { id = 36674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Iron Siegeworks", description = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge.\n\nA strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36675] = { id = 36675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Magnarok", description = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our outposts in the west. Most seem to originate from Magnarok in Frostfire Ridge.\n\nIf we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", progress = "How goes the assault, sir?", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the stone monstrosities at Magnarok in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36676] = { id = 36676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Everbloom Wilds", description = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place.\n\nBodrick Grey has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the wilds of Gorgrond, giving us more room to maneuver around them.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the botani forces in the Everbloom Wilds of Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36677] = { id = 36677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Broken Precipice", description = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them.\n\nMost of these ogron appear to be coming from the Broken Precipice, deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the ogron forces at the Broken Precipice in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36678] = { id = 36678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Mok'gol Watchpost", description = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen.\n\nIf we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Warsong forces at Mok'gol Watchpost in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36679] = { id = 36679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Darktide Roost", description = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts.\n\nThe most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should still have time to get ahead of the problem.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36680] = { id = 36680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Socrethar's Rise", description = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley.\n\nSocrathar's disciples pose a threat to draenei and our garrison alike. We need to quell them at our soonest convenience.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36681] = { id = 36681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Lost Veil Anzu", description = "Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu.\n\nBodrick Grey has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36682] = { id = 36682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Pillars of Fate", description = "Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak.\n\nBodrick Grey is concerned at their proximity to the garrison, and has put out a request that we thin their forces as soon as possible.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Shadowmoon orcs at Pillars of Fate in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36683] = { id = 36683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Skettis", description = "We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads.\n\nGuards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Adherents of Rukhmar at Skettis in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36684] = { id = 36684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle in Ashran", description = "As we do battle all across Draenor, the cowardly Horde try to seize our territory within Ashran.\n\nOur men would be inspired to see you join the battlefield, striking terror into the hearts of the Horde.", completion = "Word of your glory in battle has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Join the battle in Ashran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36685] = { id = 36685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Heart of Shattrath", description = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose.\n\nBring allies if you wish to face the Sargerei so deep within the city.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Sargerei forces deep within Shattrath City in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36686] = { id = 36686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Pit", description = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us.\n\nIf you choose the battle, bring friends. The Blackrock won't be defeated easily.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying.", objectives = "Assault the Blackrock orcs at the Pit in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36687] = { id = 36687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge at the Ring of Blood", description = "A challenge has been issued at the Ring of Blood.\n\nBring friends and do battle to prove your right as champion.", completion = "I hear you were a sight to see in the ring. I'm proud to serve by your side, commander.", objectives = "Do battle at the Ring of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36688] = { id = 36688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Skettis", description = "We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads.\n\nGuards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.", progress = "Da assault be goin' well I hope?", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the arakkoa forces at Skettis in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36689] = { id = 36689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Pillars of Fate", description = "Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak.\n\nRokhan is concerned at their proximity to key choke points leading into Shadowmoon Valley, and has put out a request that we thin their forces as soon as possible.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Shadowmoon forces at Pillars of Fate in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36690] = { id = 36690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Lost Veil Anzu", description = "Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu.\n\nRokhan has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36691] = { id = 36691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Socrethar's Rise", description = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley.\n\nSocrathar's disciples pose a threat all over Draenor. We must not allow them to gain a foothold so far from our reach.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36692] = { id = 36692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Darktide Roost", description = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts.\n\nThe most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should be able to stop their operation cold.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36693] = { id = 36693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Mok'gol Watchpost", description = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen.\n\nIf we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Warsong force at Mok'gol Watchpost in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36694] = { id = 36694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Broken Precipice", description = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them.\n\nMost of these ogron appear to be coming from the Broken Precipice, deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the ogron forces at the Broken Precipice in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36695] = { id = 36695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Everbloom Wilds", description = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place.\n\nRokhan has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the jungles of Gorgrond, giving us more room to maneuver around them.", progress = "Da assault be goin' well I hope?", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Botani forces in the Everbloom Wilds in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36696] = { id = 36696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Iron Siegeworks", description = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge.\n\nA strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36697] = { id = 36697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Magnarok", description = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our garrison. Most seem to originate from Magnarok, just to the north.\n\nIf we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the stone monstrosities at Magnarok in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36698] = { id = 36698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle in Ashran", description = "As we do battle all across Draenor, the cowardly Alliance try to seize our territory within Ashran.\n\nOur men would be inspired to see you join the battlefield, striking terror into the hearts of the Alliance.", completion = "News about da fightin' beat ya back, boss-mon. And some spoils too.\n\nDem Alliance must a been none too happy to see ya on the field.", objectives = "Join the battle in Ashran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36699] = { id = 36699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Heart of Shattrath", description = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose.\n\nBring allies if you wish to face the Sargerei so deep within the city.", progress = "Da assault be goin' well I hope?", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Sargerei force in Shattrath City in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36700] = { id = 36700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge at the Ring of Blood", description = "A challenge has been issued at the Ring of Blood.\n\nBring friends and do battle to prove your right as champion.", completion = "I been hearin' ya were a sight ya see in the ring.\n\nWe made some bets on ya. Easy money.", objectives = "Do battle at the Ring of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36701] = { id = 36701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Pit", description = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us.\n\nIf you choose the battle, bring friends. The Blackrock won't be defeated easily.", progress = "Da assault be goin' well I hope?", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with.", objectives = "Assault the Blackrock forces at the Pit in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36702] = { id = 36702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meatball", objectives = "MEATBALL FEELING BETTER NOW!\n\nMEATBALL FIGHT FOR AKIHIKÓ NOW!\n\nMEATBALL FOLLOW AKIHIKÓ WHEREVER AKIHIKÓ GO!!!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36705] = { id = 36705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Blood: Mogor!", description = "You've really done it this time, champ. Mogor has challenged you to uphold his title as lord of the ring!\n\nI wish I could give you tips to help you make it out of there in one piece, but I've never seen Mogor fight. Nobody's ever gotten this far!\n\nGood luck.", completion = "You did it. You really did it! You're the new lord of the ring!", objectives = "Defeat Mogor in the Ring of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36706] = { id = 36706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Appearance", description = "Our base on Ashran is almost complete, commander.\n\nIt would be a huge show of support if you could make a trip out there and put your stamp of approval on their staging area.\n\nI can arrange a flight if you are interested.", completion = "Commander! I am humbled to be able to serve you. The Lieutenant requests your presence.", objectives = "Speak with Private Stomphoof at Warspear in Ashran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36707] = { id = 36707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warspear Welcome", description = "Lieutenant Kragil said you might be showing up.\n\nI've been ordered to take you to the inn.", completion = "Throm-Ka, commander. I am pleased to finally meet you in person.", objectives = "Speak with Lieutenant Kragil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36708] = { id = 36708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspiring Ashran", description = "I hope you will find our facilities to be up to your high standards.\n\nThis inn is run by Narnin Dawnglow, in my opinion this is the best place to hearth in Draenor.\n\nWe have new recruits coming through the portal daily. In fact one of out latest recruits, Zarjhin, just came through the portal today.\n\nIf you are looking for weapons or armor Beska Redtusk will be happy to help.", progress = "How did your walk go?", completion = "Thank you again for taking the time to visit, commander. You have no idea how much it means to us.", objectives = "Speak with Narnin Dawnglow, Beska Redtusk, and Zarjhin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36709] = { id = 36709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Beauty", description = "Before you go, there is someone you should meet.\n\nShe might set some of your stuff on fire, but I believe she's the best mage this side of Draenor.\n\nShe belongs on the front lines with you, commander.", completion = "So, you are the commander? Sylvanas sent me to find you.", objectives = "Speak with Vivianne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36710] = { id = 36710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Arena Treasure 1" }
quests[36711] = { id = 36711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abu'gar", progress = "You thinkin' you might be able to help me out, mon?", completion = "Ya brought my gear! Well it be lookin' like my luck might be turnin' around after all!\n\nAbu'gar will be returnin' the favor, just ya wait and see!\n\nRight after I hook myself a lunker, of course..." }
quests[36712] = { id = 36712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 1" }
