quests[36718] = { id = 36718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Mill Treasure 24" }
quests[36719] = { id = 36719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Aegwynn's Retreat", description = "If we're going to defeat that demon, we need something to put us on its level. Something... powerful...\n\n<Khadgar looks thoughtfully at Atiesh, his staff.>\n\nYou need a weapon. Something of great power. And if my assumptions are correct, it shouldn't be too far from here.\n\nI can send you to go find this weapon. Speak with me when you're prepared.", sourceObjective = "Speak with Khadgar.", sourceObjectiveStatus = "unverified-source-field" }
