quests[36725] = { id = 36725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Fang-Scarred Frostwolf Axe", description = "This artifact has been restored to a remarkably excellent condition, suitable for display in your Garrison.", objectives = "Put the artifact on display.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
