quests[36741] = { id = 36741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vintage Free Action Potion", description = "I hear our heroes in the front line are becoming victim to massive amounts of snares, roots and stuns! Luckily I have just the potion for them. The recipe is a little old, but it'll work. \n\nA key ingredient I need can be found here in Ashran, at the beach near that Ogre Tower.", progress = "Have you got the pearls, {name}?", completion = "And here's your potion, {name}! If you don't have any use for it, maybe gift it to a friend who does?", objectives = "Bring Gimlett Ginfizz 10 Ashmaul Pearls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
