quests[36790] = { id = 36790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Initiate's Revenge", description = "I... I'm finished. My spirit will be with the Raven Mother soon.\n\nI beg of you, stranger... avenge me! Slay these filthy beasts.", completion = "The lives of all the flock are precious.\nI'm glad to know that his murderers have been brought to justice.\n\nThank you, {name}, you have done us a great honor.", objectives = "Kill 18 Bloodmane Saberon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36791] = { id = 36791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phantom Potion", description = "Every turn you take in Ashran you run into danger. But don't fret {name}, I've developed the perfect solution. It's my very own riff on the popular Invisibility Potion. \n\nI'm just missing one of the ingredients: cave mushrooms. \n\nLuckily, a variety grows right here in Ashran.", progress = "Are those the truffles?", completion = "Here she is! Careful with her, these potions have a reputation for mysteriously disappearing.", objectives = "Bring Gimlett Ginfizz 10 Ghost Truffles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36792] = { id = 36792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bladefist Hold" }
