quests[36794] = { id = 36794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Sylldross" }
quests[36796] = { id = 36796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flock's Revenge", description = "The Bloodmane took several of our initiates when they ambushed our ritual in Ravenskar. They must be taught that the flock will never allow such a deed to go unpunished!\n\nWe will kill one of their tribe for each of the flock that has fallen!\n\nhead into their accursed home of Bloodmane Valley and slaughter as many of them as you can find.", objectives = "Kill 18 Bloodmane Saberon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
