quests[36800] = { id = 36800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Ammonite Lunker", progress = "Woooo daddy!  Now that's a lunker {name}!  I don't think I will ever get used to fishing in lava but nothing is really normal about this crazy place.", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
quests[36801] = { id = 36801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Step Ahead", description = "Commander, Vindicator Maraad set off with Yrel and Thaelin Darkanvil to track the Iron Horde's movements in the nearby forest.\n\nThey await your arrival on a small rise to the southwest.", completion = "Ah, Commander {name}. Good to see you. Now our party is complete.", objectives = "Speak to Vindicator Maraad at Redemption Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36802] = { id = 36802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssal Gulper Lunker", progress = "I'm surprised you made it back in one piece!  Abyssal Gulpers are a delicacy to local Arakkoa in Spires of Arak.", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
quests[36803] = { id = 36803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackwater Whiptail Lunker", progress = "Those Draenei bother you over in Talador?  I never fancied them fisherman but word is they are very territorial with local fishing spots.  No matter, it looks like you got the prize this time!", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
quests[36804] = { id = 36804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Lake Lunker", progress = "That's a fine Blind Lake Lunker you got there {name}.  How long did you fight it?  Fish like these don't come around very often, but when they do, it's a fight!", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
quests[36805] = { id = 36805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fat Sleeper Lunker", progress = "Looks like you caught a Fat Sleeper Lunker there.  Can't beat that river fishing in Nagrand, hoping to get out there soon myself.", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
quests[36806] = { id = 36806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jawless Skulker Lunker", progress = "A Jawless Skulker Lunker?  Must have been fishing in Gorgrond then!  I hear lots of things grow big out there...", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
