quests[36812] = { id = 36812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Penny For Your Thoughts", objectives = "You're good people, commander.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36813] = { id = 36813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subversive Infestation", description = "As lord of the Everbloom my charge was the weaponization of nature.\n\nYou have likely seen the fruits of my labor in your journeys across my world.\n\nMy discoveries have allowed my kind to control the invasive species of Draenor through subversive infestation. I speak of total systemic control of the invading organism - the mind and the body.\n\nNow that you are my master I offer these gifts to you, but first you must retrieve my research and tools from the Everbloom.\n\nDo this and great power is yours.", progress = "Retrieve what I have asked for, master. I will show you the true strength of nature.", completion = "Within this pouch I have placed three Everbloom seeds. You merely have to crush the seed to release the spores within. Inhale deeply and let the subversive infestation take hold.\n\nOnce empowered you will become an unstoppable force of nature; though be warned, I have modified these seeds to cause you minimal harm, thus their potency is somewhat reduced.\n\nYou must not undergo the transformation too frequently.\n\nShould you require more seeds I will offer them to you - for a small price.", objectives = "Recover Phylarch's Research, Xeri'tac's Venom Gland, and 3 Depleted Everbloom Seeds from the Everbloom and return to Phylarch the Evergreen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
