quests[36829] = { id = 36829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talador - Shore Treasure - Gift of the Ancients" }
quests[36830] = { id = 36830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Council Invasion!", description = "The demons are at our heels, Commander. Cow's milk is sour. A crone gave me an evil look this morning. The sky just doesn't seem... right.", progress = "We must hold the line!", completion = "They're defeated! I'm glad we came here, Commander. To Draenor. Fighting against demons reminds me why we fight for the Alliance.", objectives = "Repel the Shadow Council invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36831] = { id = 36831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Council Invasion!", description = "There's a cold fire in my blood, Commander. Like a warlock has my heart in his claw. Let the Shadow Council show themselves!", progress = "We must hold the line!", completion = "Waugh! We beat back the demons, Commander. My blood's still boiling from it. My eyes aren't turning red, are they?", objectives = "Repel the Shadow Council invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36832] = { id = 36832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Xuk Outta Here!", objectives = "If my spirits aren't with Xuk, Xuk isn't with them. You though, Xuk likes you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36833] = { id = 36833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "May I Be of Service?", objectives = "You have impressed me greatly, {name}. If you will have me, I would like to join you at your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
