quests[36843] = { id = 36843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Came From Above", description = "Please, traveler, I need your help.\n\nAruuna, my home, has been destroyed by the arakkoa. They swooped down from their spires and killed anyone who tried to escape. My family... did not make it out.\n\n My brother Barum stayed behind to find his daughter amidst the chaos. I beseech you, please, go to Aruuna and find Barum.\n\nHe is the only family I have left.", completion = "Akhan is alive? Light bless us - some good news!", objectives = "Find Crystal-Shaper Barum near Aruuna in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
