quests[36848] = { id = 36848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Waygates", description = "Six unique gates exist in Draenor, built by ogre magi in ages past.  We've discovered their potency has not diminished over the millennia.\n\nIf you can collect enough ogre waystones to activate one of these ancient waygates, we can build a portal from your garrison to that location.", progress = "Did you activate a waygate?", completion = "Your efforts will be well rewarded, {name}.  The ancient waygates now serve you.", objectives = "Collect 25 Ogre Waystones and use them to activate an Ogre Waygate in Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
