quests[36860] = { id = 36860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Lost Veil Anzu" }
quests[36861] = { id = 36861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinchwhistle Gearworks", description = "Commander, a goblin courier arrived this morning.\n\nHe mentioned that he is from a settlement in the Spires of Arak called the Pinchwhistle Gearworks. They have requested our assistance with some sort of ecological disaster.\n\nIf we can earn their trust it'll be worth the effort. Head down there and see what sort of assistance we can provide.\n\nI've already spoken to the flight master and he's set up a special flight to get you out there.", completion = "Hey, you're from that Alliance base right?\n\nGlad you made the trip because we really could use your help!", objectives = "Speak to Dungar Longdrink to secure a flight to the Pinchwhistle Gearworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36862] = { id = 36862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinchwhistle Gearworks", description = "Commander, a courier arrived this morning.\n\nHe said he's from a goblin settlement in Spires of Arak called the Pinchwhistle Gearworks. They've asked for our assistance with some sort of ecological disaster.\n\nWe're spread thin but if we can earn their trust then we might be able to gain a valuable ally.\n\nHead down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.", completion = "Hey, you're from that Horde base right?\n\nGlad you made the trip because we really could use your help!", objectives = "Speak to Bron Skyhorn the Wingman to secure a flight to the Pinchwhistle Gearworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36863] = { id = 36863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Iron Horde Munitions" }
quests[36864] = { id = 36864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Three Feet Under", objectives = "I can honestly say I never thought I'd see the premier Horde commander walking through an Alliance garrison.\n\nThen again, I never thought I'd be caught while performing reconnaissance for the Dark Lady and stuffed in a hole in the ground left for dead.\n\nI'm clearly not going anywhere without your help. If you help me out of this hellhole, I'll serve under your banner. My solo run has been decidedly less than pleasant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36865] = { id = 36865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "UBRS Event Dungeon Reward Quest" }
quests[36866] = { id = 36866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lower Blackrock Spires Reward Quest" }
quests[36867] = { id = 36867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lower Blackrock Spires Bonus Reward Quest" }
quests[36870] = { id = 36870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luring Nat", description = "Now that you are experienced enough with Draenor fishing, we might have a shot at convincing Nat Pagle to join us out here.\n\nIf we want Nat to actually come all the way out here, we are going to have to show him real proof of the incredible catches on Draenor.  Head out to local waters here in Shadowmoon Valley and see what you can do.  All that time you spend honing your skill here in Draenor should pay off now.", progress = "Find anything worth keeping?", completion = "This will do nicely... A fish like this would be hard for anyone to deny, especially Nat!", objectives = "Catch an Arcane Trout in Shadowmoon Valley and bring it back to Segumi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36872] = { id = 36872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Austin's Folly" }
quests[36874] = { id = 36874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord of Draenor", description = "Durotan...\n\n<Raza'kul spits.>\n\nHe cowers behind the white flag of peace, relying upon diplomacy to win over our sworn enemies.\n\nEnemies that have taken our homes and driven us from our ancestral lands.\n\nThere is only one way to deal with the draenei and their newfound alliance of cowards - blood for blood.\n\nJoin me in crushing our enemies. Together we will flood this hallowed ground with the bones of the Alliance and earn tributes fit for a warchief!\n\nReturn here when your bloodthirst is sated.", progress = "I will not rest until this bloodied ground overflows with the bones of our enemies.", completion = "We may kill from sky break to sky fall and still our work will never be done. Yet at the end of days when we are measured for our accomplishments, only the bloody wake that we have left behind us will show our true strength. For this reason you must never stop the slaughter of those that would seek to harm us and our loved ones.\n\nPromise me, {name}.\n\nNever. Stop.", objectives = "Kill Enemy Players in Player versus Player combat to earn 20 Broken Bones then place an offering at the Altar of Bones to Earn a Conqueror's Tribute.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36876] = { id = 36876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord of Draenor", description = "The Exarchs do nothing but squabble amongst themselves over petty issues while our people are slaughtered in their homes by orc filth. If they will not raise a fist of defiance against our enemies, I will.\n\nI wish to join your Alliance and rid this world of Horde. ALL HORDE - \"Iron\" or otherwise.\n\nThis Altar of Bones that I stand upon represents glory in battle against our Horde enemy. Place an offering upon it and earn a conqueror's tribute worthy of your unrelenting bloodthirst.\n\nKill. Them. All.", progress = "I will not rest until this bloodied ground overflows with the bones of our enemies.", completion = "It is a start, to be certain, but there is much work to be done if Draenor is to be saved. Show no mercy, for they will show none to you.\n\nThe only warlords left upon Draenor will be you and I.", objectives = "Kill Enemy Players in Player versus Player combat to earn 20 Broken Bones then place an offering at the Altar of Bones to Earn a Conqueror's Tribute.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36877] = { id = 36877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Tormmok" }
