quests[36881] = { id = 36881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlords of Draenor: The Dark Portal", description = "{name}, is it? I'm glad you're here. We can use every able-bodied {class} that we can get.\n\nI am assembling a coalition of Azeroth's strongest to step through this Dark Portal and stop the Iron Horde invasion. This may be the only way to save Azeroth.\n\nWill you join us?", completion = "Looks to me like we ended up in the right place.", objectives = "Speak with Archmage Khadgar at the foot of the Dark Portal in Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36882] = { id = 36882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Angler Returns", description = "What's this species, an arcane trout you say? I have never even heard of a fish like this, much less seen one in person!\n\nI have to find more fish like this, it's what I live for! And if the fishing is as good as you say it is, there is just no way I can pass this opportunity up.  Take this page from my journal as proof that you found me and I will meet you back at your Garrison.", progress = "You found Nat? The real Nat Pagle?!", completion = "We should really catch some big one's when Nat's gets here!", objectives = "Return to Segumi with Nat's journal page as proof that you found him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36884] = { id = 36884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen Snout", progress = "GOT SOMETHING FOR ME, CALLMEDEAD?", completion = "OOH IT'S SO RUBBERY. AND STILL WARM. GOOD WORK!" }
quests[36885] = { id = 36885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Waygate" }
