quests[36887] = { id = 36887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette 029 - Hermit Palefur" }
quests[36889] = { id = 36889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Hunter - Hunted", description = "Our enemies surround us, and with each passing day their numbers grow. It is time to make a decisive strike against their armies, champion.\n\nAround me stand effigies of our most hated adversaries. You will be their downfall, {name}. You will become nemesis and they will run in fear at the sight of you.\n\nNow select the target of your rage and burn in effigy that race which you mean to eradicate. Speak to me when you have made your selection.", completion = "A last warning: once you have accepted this choice you cannot reverse it or make a new choice until you complete your mission.\n\nIf your choice is certain, your aim will be true.\n\nStrike fear in the hearts and minds of the enemy! For the Horde. For Draenor.", objectives = "Burn a Nemesis Effigy at the Gladiator's Sanctum then speak to Raza'kul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36890] = { id = 36890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis Flag, Human/Orc" }
