quests[36896] = { id = 36896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis Flag, Pandaren (A/H)" }
quests[36897] = { id = 36897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a human in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", progress = "Have you recovered the heart of a worthy foe?", completion = "With this heart you will see and hear things as only the great spirits can. Your enemy will be unable to hide from your unrelenting assaults.", objectives = "Kill a Human Player in Player versus Player combat while in Draenor and retrieve their Human Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
