quests[36935] = { id = 36935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phantom Potion", description = "Every turn you take in Ashran you run into danger. But don't fret {name}, I've developed the perfect solution. It's my very own riff on the popular Invisibility Potion. \n\nI'm just missing one of the ingredients: cave mushrooms. \n\nLuckily, a variety grows right here in Ashran.", progress = "Are those the truffles?", completion = "Here she is! Careful with her, these potions have a reputation for mysteriously disappearing.", objectives = "Bring Tyra Silverblood 10 Ghost Truffles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
